1: META { id: "ail-project-rules" version: "0.3" priority: HIGH }
2: 
3: RULE R001 {
4:   priority: CRITICAL
5:   scope: "**/*.go"
6:   when { file.language == GO }
7:   do { use_ascii_hyphen preserve_existing_comments }
8:   never { emit_typographic_dash rewrite_adjacent_comments }
9:   fallback { ask_user_before_inserting_symbol }
10: }
11: 
12: RULE R002 {
13:   priority: HIGH
14:   scope: "**/*.go"
15:   when { file.language == GO }
16:   do { keep_files_under_700_lines extract_focused_submodules }
17:   never { create_god_files }
18:   fallback { split_by_domain_concern }
19: }
20: 
21: RULE R003 {
22:   priority: HIGH
23:   scope: "**/*.go"
24:   when { platform.has_golangci_lint }
25:   do { run_all_tests_after_edits fix_every_diagnostic_in_touched_files }
26:   never { ignore_warnings }
27:   verify { tests_pass vet_clean }
28:   fallback { report_remaining_diagnostics }
29: }
30: 
31: RULE R004 {
32:   priority: CRITICAL
33:   when { agent.about_to_run_command }
34:   do { stay_local ask_permission_before_remote_operations }
35:   never { touch_production use_production_credentials }
36:   fallback { stop_and_ask_user }
37: }
38: 
39: RULE R005 {
40:   priority: HIGH
41:   when { agent.choosing_approach }
42:   do { state_assumptions_explicitly prefer_simplicity make_surgical_changes }
43:   never { add_speculative_abstractions improve_unrelated_code }
44:   fallback { present_tradeoffs_and_wait }
45: }
46: 
47: RULE R006 {
48:   priority: HIGH
49:   when { agent.defining_success }
