51:   never { claim_success_without_evidence }
52:   fallback { report_exact_coverage }
53: }
54: 
55: RULE R007 {
56:   priority: MEDIUM
57:   when { project.has_shared_concept }
58:   do { use_one_directory_per_concept search_before_creating }
59:   never { duplicate_implementations }
60:   fallback { extend_existing_implementation }
61: }
62: 
63: RULE R008 {
