48: // sanitize prevents rule text from containing delimiter-like sequences.
49: func (r *renderer) sanitize(text string) string {
50: 	if strings.Contains(text, "BEGIN AIL SYSTEM RULES") || strings.Contains(text, "END AIL SYSTEM RULES") {
51: 		r.report("RENDER_NESTED_DELIMITER", "Rule text contains a nested AIL delimiter and was escaped")
52: 	}
53: 	text = strings.ReplaceAll(text, "<!--", "&lt;!--")
54: 	text = strings.ReplaceAll(text, "-->", "--&gt;")
55: 	return text
56: }
