149: func (r *renderer) renderRules(ir *core.IR) string {
150: 	var out strings.Builder
151: 	for _, rule := range ir.Rules {
152: 		switch r.options.Mode {
153: 		case core.ModeCompact:
154: 			out.WriteString(r.compactRule(rule) + "\n")
155: 		case core.ModeVerbose:
156: 			out.WriteString(r.structuredRule(rule, true))
157: 		default:
158: 			out.WriteString(r.structuredRule(rule, false))
159: 		}
160: 	}
161: 	return out.String()
162: }
163: 
164: func (r *renderer) hostHeader(ir *core.IR) string {
165: 	switch r.options.Host {
166: 	case core.HostCursor:
167: 		globs := ""
168: 		if len(ir.Provenance) > 0 {
169: 			globs = ir.Provenance[0].File
170: 		}
171: 		return fmt.Sprintf("---\ndescription: AIL operational instructions (%s)\nglobs: %s\nalwaysApply: true\n---\n\n", r.options.Mode, globs)
172: 	case core.HostOpenCode:
173: 		return "# AIL Operational Instructions\n\n"
174: 	case core.HostAgentsMD:
175: 		return "# Project Agent Instructions\n\nGenerated by AIL. Preserve this file when regenerating.\n\n"
176: 	case core.HostMarkdown:
177: 		return "# AIL Instructions\n\n"
178: 	default:
179: 		return ""
180: 	}
181: }
