67: 		fmt.Sprintf("%s [%s]", rule.ID, rule.Priority),
68: 		"WHEN: " + r.list(rule.When),
69: 		"DO: " + r.list(rule.Do),
70: 		"NEVER: " + r.list(rule.Never),
71: 		"VERIFY: " + r.list(rule.Verify),
72: 		"FALLBACK: " + r.list(rule.Fallback),
73: 		"ASSERT: " + r.list(rule.Assert),
74: 	}
75: 	if rule.Scope != "" {
76: 		parts = append(parts, "SCOPE: "+rule.Scope)
77: 	}
78: 	if len(rule.Requires) > 0 {
79: 		parts = append(parts, "REQUIRES: "+r.list(rule.Requires))
80: 	}
81: 	if len(rule.Inherit) > 0 {
82: 		parts = append(parts, "INHERIT: "+r.list(rule.Inherit))
83: 	}
84: 	if rule.Execution != "" {
85: 		parts = append(parts, "EXECUTION: "+rule.Execution)
86: 	}
87: 	return r.sanitize(strings.Join(parts, " | "))
88: }
