90: func (r *renderer) structuredRule(rule core.IRRule, verbose bool) string {
91: 	var out strings.Builder
92: 	out.WriteString("### " + r.sanitize(rule.ID) + "\n\n")
93: 	if verbose {
94: 		out.WriteString("This rule is an operational instruction. Apply it to matching work.\n\n")
95: 	}
96: 	fmt.Fprintf(&out, "- Priority: %s\n", rule.Priority)
97: 	if rule.Scope != "" {
98: 		fmt.Fprintf(&out, "- Scope: %s\n", r.sanitize(rule.Scope))
99: 	}
100: 	if len(rule.When) > 0 {
101: 		out.WriteString("- When:\n")
102: 		for _, item := range rule.When {
103: 			fmt.Fprintf(&out, "  - %s\n", r.sanitize(item))
104: 		}
105: 	}
106: 	writeTerms := func(label string, values []string) {
107: 		if len(values) == 0 {
108: 			return
109: 		}
110: 		fmt.Fprintf(&out, "- %s:\n", label)
111: 		for _, item := range values {
112: 			fmt.Fprintf(&out, "  - %s\n", r.sanitize(item))
113: 		}
114: 	}
115: 	writeTerms("Do", rule.Do)
116: 	writeTerms("Never", rule.Never)
117: 	writeTerms("Verify", rule.Verify)
118: 	writeTerms("Fallback", rule.Fallback)
119: 	writeTerms("Assert", rule.Assert)
120: 	if len(rule.Requires) > 0 {
121: 		fmt.Fprintf(&out, "- Requires: %s\n", r.sanitize(r.list(rule.Requires)))
122: 	}
123: 	if len(rule.Inherit) > 0 {
124: 		fmt.Fprintf(&out, "- Inherit: %s\n", r.sanitize(r.list(rule.Inherit)))
125: 	}
126: 	if rule.Execution != "" {
127: 		fmt.Fprintf(&out, "- Execution: %s\n", r.sanitize(rule.Execution))
128: 	}
129: 	if verbose {
130: 		keys := make([]string, 0, len(rule.Context))
131: 		for key := range rule.Context {
132: 			keys = append(keys, key)
133: 		}
134: 		sort.Strings(keys)
135: 		for _, key := range keys {
136: 			fmt.Fprintf(&out, "- Context %s: %s\n", r.sanitize(key), r.sanitize(rule.Context[key].String()))
137: 		}
138: 		if r.options.IncludeProvenance {
139: 			fmt.Fprintf(&out, "- Source: %s:%d:%d\n", r.sanitize(rule.Source.File), rule.Source.Line, rule.Source.Column)
140: 		}
141: 		if len(rule.InheritedFrom) > 0 {
142: 			fmt.Fprintf(&out, "- Inherited from: %s\n", r.sanitize(r.list(rule.InheritedFrom)))
143: 		}
144: 	}
145: 	out.WriteString("\n")
146: 	return out.String()
147: }
