149: func (r *renderer) renderRules(ir *core.IR) string {
150: 	var out strings.Builder
151: 	for _, rule := range ir.Rules {
152: 		switch r.options.Mode {
153: 		case core.ModeCompact:
154: 			out.WriteString(r.compactRule(rule) + "\n")
155: 		case core.ModeVerbose:
156: 			out.WriteString(r.structuredRule(rule, true))
157: 		default:
158: 			out.WriteString(r.structuredRule(rule, false))
159: 		}
160: 	}
161: 	return out.String()
162: }
