171: 		return fmt.Sprintf("---\ndescription: AIL operational instructions (%s)\nglobs: %s\nalwaysApply: true\n---\n\n", r.options.Mode, globs)
172: 	case core.HostOpenCode:
173: 		return "# AIL Operational Instructions\n\n"
