290: // VerifyTask runs the task verification command inside the isolated workspace.
291: func VerifyTask(record *RunRecord, task Task, timeout time.Duration) error {
292: 	if task.VerifyCommand == "" || record.WorkDir == "" {
293: 		return nil
294: 	}
295: 	if timeout <= 0 {
296: 		timeout = 2 * time.Minute
297: 	}
298: 	ctx, cancel := context.WithTimeout(context.Background(), timeout)
299: 	defer cancel()
300: 	parts := strings.Fields(task.VerifyCommand)
301: 	if len(parts) == 0 {
302: 		return nil
303: 	}
304: 	cmd := exec.CommandContext(ctx, parts[0], parts[1:]...)
305: 	cmd.Dir = record.WorkDir
306: 	output, err := cmd.CombinedOutput()
307: 	record.VerifyOutput = string(output)
308: 	if exitError, ok := err.(*exec.ExitError); ok {
309: 		record.VerifyExitCode = exitError.ExitCode()
310: 	} else if err != nil {
311: 		record.VerifyExitCode = -1
312: 	}
313: 	record.VerifyPassed = err == nil
314: 	return nil
315: }
