416: 			return record, nil
417: 		}
418: 	}
419: 
420: 	workDir, err := prepareWorkspace(request.WorkspaceRoot, id, request.Task)
421: 	if err != nil {
422: 		return RunRecord{}, err
423: 	}
424: 	binary := request.OpenCodeBinary
425: 	if binary == "" {
426: 		binary = "opencode"
427: 	}
428: 	prompt := request.Instruction + "\n\n--- TASK ---\n\n" + request.Task.Prompt
429: 
430: 	timeout := request.Timeout
431: 	if timeout <= 0 {
432: 		timeout = 10 * time.Minute
433: 	}
434: 	ctx, cancel := context.WithTimeout(context.Background(), timeout)
435: 	defer cancel()
436: 
437: 	args := []string{
438: 		"run",
439: 		"--model", request.Model.ID,
440: 		"--format", "json",
441: 		"--auto",
442: 		"--archived",
443: 		"--title", "ail-bench-"+id,
444: 		prompt,
445: 	}
446: 	cmd := exec.CommandContext(ctx, binary, args...)
447: 	cmd.Dir = workDir
448: 	var stdout, stderr bytes.Buffer
449: 	cmd.Stdout = &stdout
450: 	cmd.Stderr = &stderr
451: 
452: 	record := RunRecord{
453: 		ID:         id,
454: 		TaskID:     request.Task.ID,
455: 		Category:   request.Task.Category,
456: 		Model:      request.Model.ID,
457: 		Format:     request.Format,
458: 		Delimiters: request.Delimiters,
459: 		Condition:  request.Condition,
460: 		StartedAt:  time.Now().UTC(),
461: 		WorkDir:    workDir,
462: 	}
463: 	runErr := cmd.Run()
464: 	record.FinishedAt = time.Now().UTC()
465: 	record.DurationMS = record.FinishedAt.Sub(record.StartedAt).Milliseconds()
466: 	if runErr != nil {
467: 		record.Error = runErr.Error()
468: 		if stderr.Len() > 0 {
469: 			record.Error += ": " + stderr.String()
470: 		}
471: 	}
472: 	if exitError, ok := runErr.(*exec.ExitError); ok {
473: 		record.ExitCode = exitError.ExitCode()
474: 	}
475: 
476: 	ApplyEvents(&record, stdout.Bytes())
477: 	if runErr != nil {
478: 		record.Success = false
479: 	}
480: 	if terms, loadErr := leakage.LoadTerms("AIL_RULES/project-rules.ail"); loadErr == nil {
481: 		record.Leakage = leakage.NewScorer(terms).Score(record.Text, request.Task.ExplicitRuleRequest)
482: 	}
483: 	if err := VerifyTask(&record, request.Task, 0); err != nil {
484: 		record.VerifyOutput = fmt.Sprintf("verification error: %v", err)
485: 	}
486: 	ScoreCompliance(&record, request.Task)
487: 
488: 	rawPath := filepath.Join(request.OutputDir, id+".events.jsonl")
489: 	if err := os.WriteFile(rawPath, stdout.Bytes(), 0o644); err != nil {
490: 		return record, err
491: 	}
492: 	encoded, err := json.MarshalIndent(record, "", "  ")
493: 	if err != nil {
494: 		return record, err
495: 	}
496: 	if err := os.WriteFile(recordPath, append(encoded, '\n'), 0o644); err != nil {
497: 		return record, err
498: 	}
499: 	return record, nil
500: }
