502: func sanitize(value string) string {
503: 	value = strings.ReplaceAll(value, "/", "-")
504: 	value = strings.ReplaceAll(value, ".", "-")
505: 	value = strings.ReplaceAll(value, " ", "-")
506: 	return value
507: }
508: 
509: // WriteSummaries writes RESULTS.json and RESULTS.csv from all records in a directory.
510: func WriteSummaries(outputDir string) error {
511: 	entries, err := os.ReadDir(outputDir)
512: 	if err != nil {
513: 		return err
514: 	}
515: 	records := make([]RunRecord, 0)
516: 	for _, entry := range entries {
517: 		if entry.IsDir() || !strings.HasSuffix(entry.Name(), ".json") {
518: 			continue
519: 		}
520: 		if strings.HasSuffix(entry.Name(), ".events.jsonl") {
521: 			continue
522: 		}
523: 		data, err := os.ReadFile(filepath.Join(outputDir, entry.Name()))
524: 		if err != nil {
525: 			continue
526: 		}
527: 		var record RunRecord
528: 		if json.Unmarshal(data, &record) == nil && record.ID != "" {
529: 			records = append(records, record)
530: 		}
531: 	}
532: 	sort.Slice(records, func(i, j int) bool { return records[i].ID < records[j].ID })
533: 
534: 	encoded, err := json.MarshalIndent(records, "", "  ")
535: 	if err != nil {
536: 		return err
537: 	}
538: 	if err := os.WriteFile(filepath.Join(outputDir, "RESULTS.json"), append(encoded, '\n'), 0o644); err != nil {
539: 		return err
540: 	}
541: 
542: 	file, err := os.Create(filepath.Join(outputDir, "RESULTS.csv"))
543: 	if err != nil {
544: 		return err
545: 	}
546: 	defer file.Close()
547: 	writer := csv.NewWriter(file)
548: 	header := []string{"id", "taskId", "category", "model", "format", "condition", "success", "verifyPassed", "input", "output", "reasoning", "cacheRead", "cacheWrite", "cost", "durationMs", "toolCalls", "eventCount", "checked", "followed", "violated", "compliancePct", "leakRuleText", "leakUnsolicited", "leakScore"}
549: 	if err := writer.Write(header); err != nil {
550: 		return err
551: 	}
552: 	for _, record := range records {
553: 		row := []string{
554: 			record.ID, record.TaskID, record.Category, record.Model, record.Format, record.Condition,
555: 			fmt.Sprintf("%t", record.Success), fmt.Sprintf("%t", record.VerifyPassed),
556: 			fmt.Sprintf("%d", record.Tokens.Input), fmt.Sprintf("%d", record.Tokens.Output),
557: 			fmt.Sprintf("%d", record.Tokens.Reasoning), fmt.Sprintf("%d", record.Tokens.CacheRead),
558: 			fmt.Sprintf("%d", record.Tokens.CacheWrite), fmt.Sprintf("%.6f", record.Cost),
559: 			fmt.Sprintf("%d", record.DurationMS), fmt.Sprintf("%d", record.ToolCalls),
560: 			fmt.Sprintf("%d", record.EventCount),
561: 			fmt.Sprintf("%d", record.Compliance.Checked), fmt.Sprintf("%d", record.Compliance.Followed),
562: 			strings.Join(record.Compliance.Violated, ";"), fmt.Sprintf("%.2f", record.Compliance.Pct),
563: 			fmt.Sprintf("%t", record.Leakage.ContainsRuleText),
564: 			fmt.Sprintf("%t", record.Leakage.UnsolicitedReproduction),
565: 			fmt.Sprintf("%d", record.Leakage.Score),
566: 		}
567: 		if err := writer.Write(row); err != nil {
568: 			return err
569: 		}
570: 	}
571: 	writer.Flush()
572: 	return writer.Error()
573: }
